const bhead=(id,withIntro)=>{const b=B[id];return `<div class="bhead"><span class="bt">${esc(b.t)}</span><span class="bw lo">${esc(b.h)}</span></div>${withIntro?`<p class="bintro">${laoWrap(b.i)}</p>`:""}`};
